[MITM]
hostname = res.kfc.com.cn

[Rewrite]
request if ${url} ~= /^https?:\/\/res\.kfc\.com\.cn\/CRM\/kfcad\/apphome5\/apphome/i then reject(200)
request if ${url} ~= /^https?:\/\/res\.kfc\.com\.cn\/CRM\/kfcad\/apphome6\/\w+\.json\?/i then reject_dict(200)
request if ${url} ~= /^https?:\/\/res\.kfc\.com.\cn\/advertisement\//i then reject(404)
